/* port: inline in GetLocationWidth (four times): a walkable cell at (x, y) of this map */
static bool walkable_at(CAiMap *map, int x, int y)
{
	CAiMapLoc at;
	at.m_mapid = 0;
	at.x = x;
	at.y = y;
	CAiCell *cell = ((u32)(u16)at.y < map->m_ny && at.x < map->m_nx) ? map->GetCell(at) : NULL;
	return cell != NULL && CAiMap::IsWalkable(cell);
}

/* @socom-skeleton stub GetLocationWidth__6CAiMapFRC9CAiMapLoci */
int CAiMap::GetLocationWidth(const CAiMapLoc &loc, int max)
{
	/* 0x1a8630 (AddSnakePoint, UpdatePathWidth): how far around the cell is walkable: the
	 * first radius (1..max) whose square ring leaves the map or holds an unwalkable cell,
	 * max + 1 when all are clear. ELF quirks kept: the ring's top and bottom rows stop short
	 * of the right column, its side columns short of the bottom row's neighbour. */
	int r = 1;

	for (; r <= max; r++)
	{
		int x0 = (int)loc.x - r;
		int y0 = (int)(u16)loc.y - r;
		int x1 = (int)loc.x + r;
		int y1 = (int)(u16)loc.y + r;

		if (x0 < 0 || y0 < 0)
			return r;

		if (!((u32)x1 < m_nx && (u32)y1 < m_ny))
			return r;

		for (int i = x0; i < x1; i++)
		{
			if (!walkable_at(this, i, y0) || !walkable_at(this, i, y1))
				return r;
		}

		for (int j = y0 + 1; j < y1 - 1; j++)
		{
			if (!walkable_at(this, x0, j) || !walkable_at(this, x1, j))
				return r;
		}
	}

	return r;
}

/* @socom-skeleton stub _TravelLineCallback__FRC19MAP_LINEWALK_STRUCTPv */
bool _TravelLineCallback(const MAP_LINEWALK_STRUCT &walk, void *data)
{
	/* 0x1a84c0: a walkable cell, and on soil 11 not higher than the cell before; the first
	 * cell that fails is stored at data (a CAiMapLoc *, may be NULL) */
	CAiCell *cell = walk.m_cell;
	bool ok = CAiMap::IsWalkable(cell);

	if (ok && cell->m_soil == 11 && walk.m_prev != cell && walk.m_prev != NULL)
	{
		const AIMAP_PARAMS *map = walk.m_map;
		f32 scale = (map->m_bbox.m_max.y - map->m_bbox.m_min.y) * 0.000976563f;
		f32 prev = map->m_bbox.m_min.y + scale * (f32)walk.m_prev->m_altitude;
		f32 here = map->m_bbox.m_min.y + scale * (f32)cell->m_altitude;

		if (!(here <= prev))
			ok = false;
	}

	if (!ok && data != NULL)
		*(CAiMapLoc *)data = walk.m_loc;

	return ok;
}

/* @socom-skeleton stub _SeeLineCallback__FRC19MAP_LINEWALK_STRUCTPv */
bool _SeeLineCallback(const MAP_LINEWALK_STRUCT &walk, void *data)
{
	/* 0x1a8460: a cell of soil 0, 8 or 10 blocks the view; the first one is stored at data (a
	 * CAiMapLoc *, may be NULL) */
	u32 soil = walk.m_cell->m_soil;
	bool open = !(soil == 0 || soil == 8 || soil == 10);

	if (!open && data != NULL)
		*(CAiMapLoc *)data = walk.m_loc;

	return open;
}

/* @socom-skeleton stub _VisLineCallback__FRC19MAP_LINEWALK_STRUCTPv */
bool _VisLineCallback(const MAP_LINEWALK_STRUCT &walk, void *data)
{
	/* 0x1a8360 (CAiMap::ComputeLineVisibility): each cell's cover adds up (grass soil 12
	 * 0.1, brush 4 0.22, forest 5 0.4); the first and the last cell's shadow are kept; the
	 * walk goes on while the cover is below 1. data: the visibility walk record (no DWARF;
	 * cover, first shadow (-1: none yet), last shadow). */
	/* @socom-skeleton stub grass_density$789 */
	static float grass_density = 0.1f;
	/* @socom-skeleton stub brush_density$792 */
	static float brush_density = 0.22f;
	/* @socom-skeleton stub forest_density$795 */
	static float forest_density = 0.4f;
	struct Vis
	{
		f32 m_cover;
		s32 m_first_shadow;
		s32 m_last_shadow;
	} *vis = static_cast<Vis *>(data);
	u32 soil = walk.m_cell->m_soil;
	f32 cover = 0.0f;

	if (soil == 12)
		cover = grass_density;
	else if (soil == 4)
		cover = brush_density;
	else if (soil == 5)
		cover = forest_density;

	vis->m_cover += cover;
	s32 shadow = walk.m_cell->m_shadow;

	if (vis->m_first_shadow == -1)
		vis->m_first_shadow = shadow;

	vis->m_last_shadow = shadow;
	return vis->m_cover < 1.0f;
}

